using Clock=std::chrono::steady_clock;
static double elapsed(Clock::time_point start){return std::chrono::duration<double>(Clock::now()-start).count();}
static void ok(saf_status s){if(s!=SAF_OK)throw std::runtime_error(std::string("core: ")+saf_last_error());}
template<class T,class F>static std::vector<T> query(F f){size_t n=0;ok(f(nullptr,0,&n));std::vector<T>v(n);ok(f(v.data(),v.size(),&n));return v;}
template<class T>static void array(std::ostream&o,const std::vector<T>&v,bool none=false){o<<'[';for(size_t i=0;i<v.size();++i){if(i)o<<',';if(none&&v[i]==SAF_NONE)o<<"null";else o<<v[i];}o<<']';}
static void bools(std::ostream&o,const std::vector<uint8_t>&v){o<<'[';for(size_t i=0;i<v.size();++i){if(i)o<<',';o<<(v[i]?"true":"false");}o<<']';}
static void annotations(std::ostream&o,const Tree&t){o<<'[';for(size_t i=0;i<t.nodes.size();++i){if(i)o<<',';auto&n=t.nodes[i];o<<"{\"id\":"<<i<<",\"label\":"<<json(n.label)<<",\"length_token\":"<<(n.has_length?json(n.length):"null")<<",\"comments\":[";for(size_t j=0;j<n.comments.size();++j){if(j)o<<',';o<<json(n.comments[j]);}o<<"]}";}o<<']';}
struct Group{std::string hex;size_t left,right;std::vector<size_t>members;};
struct Coverage{std::unique_ptr<saf_coverage,decltype(&saf_coverage_destroy)>h{nullptr,saf_coverage_destroy};std::string id,mask;std::vector<size_t>axis;std::vector<uint8_t>structural,eligible;std::vector<Group>groups;};
static std::shared_ptr<Coverage> prepare_cov(saf_reference*r,const std::vector<uint64_t>&mask,size_t axes){auto c=std::make_shared<Coverage>();saf_coverage*p=nullptr;ok(saf_coverage_create(r,mask.data(),mask.size(),&p));c->h.reset(p);c->mask=bits_hex(mask);c->id=digest(c->mask);c->axis.resize(axes);c->structural.resize(axes);c->eligible.resize(axes);ok(saf_coverage_axes(p,c->axis.data(),c->structural.data(),c->eligible.data(),axes));saf_coverage_info ci;ok(saf_coverage_get_info(p,&ci));for(size_t g=0;g<ci.n_projections;++g){saf_split_info si;auto w=query<uint64_t>([&](auto a,auto b,auto d){return saf_coverage_projection(p,g,a,b,d,&si);});auto members=query<size_t>([&](auto a,auto b,auto d){return saf_coverage_members(p,g,a,b,d);});c->groups.push_back({bits_hex(w),si.side_count,si.other_count,std::move(members)});}return c;}
static void coverage_json(std::ostream&o,const Coverage&c){o<<"{\"coverage_id\":"<<json(c.id)<<",\"mask_hex\":"<<json(c.mask)<<",\"structural_axes\":[";bool first=true;for(size_t a=0;a<c.structural.size();++a)if(c.structural[a]){if(!first)o<<',';o<<a;first=false;}o<<"],\"axis_to_projection\":";array(o,c.axis,true);o<<",\"eligible\":";bools(o,c.eligible);o<<",\"projections\":[";for(size_t g=0;g<c.groups.size();++g){if(g)o<<',';auto&x=c.groups[g];o<<"{\"id\":"<<g<<",\"split_hex\":"<<json(x.hex)<<",\"side_count\":"<<x.left<<",\"other_count\":"<<x.right<<",\"members\":";array(o,x.members);o<<'}';}o<<"]}\n";}
struct Writers{fs::path dir;std::map<std::string,std::unique_ptr<std::ofstream>>files;std::string injection;std::ostream&get(const std::string&n){auto&i=files[n];if(!i){i.reset(new std::ofstream(dir/n,std::ios::binary));i->imbue(std::locale::classic());*i<<std::setprecision(17);if(!*i)throw std::runtime_error("output open: "+n);}return *i;}void close(){for(auto&kv:files){auto&f=*kv.second;if(injection=="write"){f.setstate(std::ios::badbit);injection.clear();}f.flush();if(!f)throw std::runtime_error("output flush: "+kv.first);f.close();if(injection=="close"){f.setstate(std::ios::badbit);injection.clear();}if(f.fail())throw std::runtime_error("output close: "+kv.first);}}};
struct Values{std::vector<double>v;std::vector<uint8_t>a;explicit Values(size_t n):v(n,NAN),a(n,0){}saf_value_buffer buffer(){return {v.data(),a.data(),v.size()};}};
static void value_json(std::ostream&o,const Values&v,size_t i){bool has=i<v.a.size()&&v.a[i];o<<"\"value\":";if(has)o<<v.v[i];else o<<"null";o<<",\"numeric_available\":"<<(has?"true":"false");}
struct Edge{std::string hex;std::vector<size_t>sources;};
static std::vector<Edge> edge_queries(saf_mapping*m,size_t n){std::vector<Edge>es;for(size_t e=0;e<n;++e){auto w=query<uint64_t>([&](auto a,auto b,auto c){return saf_mapping_gene_split(m,e,a,b,c,nullptr);});auto s=query<size_t>([&](auto a,auto b,auto c){return saf_mapping_gene_sources(m,e,a,b,c);});es.push_back({bits_hex(w),std::move(s)});}return es;}
struct Options{std::string reference,genes,taxa,out,scope="full",role="free",format="tsv",inject,unmatched="default";bool numeric=true;};
static Options options(int argc,char**argv){Options o;std::set<std::string>seen;for(int i=1;i<argc;++i){std::string k=argv[i];if(!seen.insert(k).second)throw std::runtime_error("duplicate option "+k);if(k=="--no-numeric"){o.numeric=false;continue;}if(i+1==argc)throw std::runtime_error("missing option value "+k);std::string v=argv[++i];if(k=="--reference")o.reference=v;else if(k=="--genes")o.genes=v;else if(k=="--taxa")o.taxa=v;else if(k=="--out")o.out=v;else if(k=="--scope")o.scope=v;else if(k=="--role")o.role=v;else if(k=="--gene-format")o.format=v;else if(k=="--unmatched-splits"){if(v!="on"&&v!="off")throw std::runtime_error("--unmatched-splits requires on or off");o.unmatched=v;}else if(k=="--inject-io-failure")o.inject=v;else throw std::runtime_error("unknown option "+k);}if(o.reference.empty()||o.out.empty())throw std::runtime_error("--reference and --out required");if(o.scope!="matrix"&&o.scope!="full"&&o.scope!="support"&&o.scope!="truth")throw std::runtime_error("invalid scope");if(o.unmatched=="on"&&o.scope!="full"&&o.scope!="support")throw std::runtime_error("--unmatched-splits on requires full or support scope");if(o.role!="fixed"&&o.role!="free")throw std::runtime_error("invalid role");if(o.scope=="support"&&o.role!="free")throw std::runtime_error("support requires free role");if(o.scope=="truth"){o.numeric=false;if(o.taxa.empty()||!o.genes.empty())throw std::runtime_error("truth requires --taxa only");}else if(o.genes.empty()||!o.taxa.empty())throw std::runtime_error("mapping requires --genes only");if(o.scope=="support")o.numeric=false;if(o.format!="tsv"&&o.format!="prefix-newick")throw std::runtime_error("invalid gene format");if(!o.inject.empty()&&o.inject!="read"&&o.inject!="write"&&o.inject!="close")throw std::runtime_error("invalid I/O injection");return o;}
static void table_values(std::ostream&o,const std::string&id,const Values&v){o<<id;for(size_t a=0;a<v.v.size();++a){o<<'\t';if(v.a[a])o<<v.v[a];else o<<"NA";}o<<'\n';}
static void checked_file(const fs::path&p,const std::string&s){std::ofstream f(p,std::ios::binary);f<<s;f.flush();if(!f)throw std::runtime_error("file write: "+p.string());f.close();if(f.fail())throw std::runtime_error("file close: "+p.string());}
